# Resumen por clase (8929aea). Texto en espanol; los [[...]] son notas del Vault.
S = {}
T = {}
# ---------------- models ----------------
S['Address'] = 'Dirección de envío de una Cuenta: calle, altura, piso, ciudad, [[Province]], código postal y notas, más la marca `archived`. Es inmutable. `withCityAndProvinceOnly` devuelve una copia sin calle ni altura: es lo que ve el publicante mientras no hay una venta en curso. Ver [[Addresses and payment flow]].'
S['Album'] = 'La obra del catálogo compartido: título, artista, año de lanzamiento, [[Genre]] y una portada heredada opcional. Su identidad es artista, título normalizado y año. Varias publicaciones de distintas Cuentas apuntan al mismo álbum. Ver [[Publish flow]].'
S['Artist'] = 'Artista del catálogo compartido: id y nombre visible. La identidad (nombre normalizado) y la frase de búsqueda viven en la tabla, no en el modelo. Ver [[Publish flow]].'
S['Cart'] = 'El carrito tal como se muestra: los grupos por publicante, la cantidad de vinilos y el total con los precios actuales. No es una entidad de venta; los totales llegan calculados desde [[CartServiceImpl]]. Ver [[Cart flow]].'
S['CartCheckout'] = 'Lo que necesita la pantalla del carrito: el [[Cart]] y las [[ShippingOptions]] del comprador. Ver [[Cart flow]].'
S['CartCheckoutResult'] = 'Resultado de enviar el carrito: cuántas Consultas se crearon y cuántos vinilos se omitieron porque dejaron de estar disponibles. La bandeja de enviadas lo muestra como aviso. Ver [[Cart flow]].'
S['CartItem'] = 'Un vinilo dentro del carrito, con lo que muestra la pantalla: post, publicante, título, artista, año, imagen opcional y precio actual. Solo llegan los que todavía se pueden consultar. Ver [[Cart flow]].'
S['CartSellerGroup'] = 'Los vinilos del carrito que son de un mismo publicante. Al enviar, a ese publicante le llega un solo correo. Ver [[Cart flow]].'
S['Condition'] = 'Estado físico del ejemplar: `NEW` o `USED`. Obligatorio al publicar; filtro del catálogo. La base lo refuerza con un `CHECK`.'
S['ContactState'] = 'Qué puede hacer una Cuenta con un post: `CONTACTABLE`, `OPEN_INQUIRY`, `UNAVAILABLE` u `OWN_POST`. Lo calcula [[ContactRules]] y lo usan el contacto, el carrito y la ficha.'
S['EmailRules'] = 'Una sola regla para guardar y buscar un correo: sin espacios y en minúsculas. La comparten [[UserServiceImpl]] y [[UserJdbcDao]], así el mismo correo escrito distinto es la misma Cuenta.'
S['EmailVerificationToken'] = 'Fila de `email_verification_tokens`: id, Cuenta, token y fecha de emisión. La fecha sirve para el tope de un minuto entre reenvíos. No tiene vencimiento. Ver [[Tokens and email links]].'
S['Genre'] = 'Quince géneros del catálogo, incluido `OTHER`. Se guarda en el álbum, es obligatorio al publicar y la base lo refuerza con un `CHECK`. El nombre visible sale de i18n.'
S['Image'] = 'Una imagen guardada: id, tipo de contenido y bytes. La usan fotos de publicaciones, portadas heredadas y avatares. Ver [[Cover image flow]].'
S['ImageRules'] = 'Qué imagen se acepta: PNG, JPEG o WEBP cuya firma de bytes coincide con el tipo declarado, hasta 5 MiB, hasta 5 fotos por publicación, y 26 MiB por request. La usan los validadores de formulario, las vistas y [[ImageServiceImpl]]. Ver [[Cover image flow]].'
S['ImageUpload'] = 'Un archivo subido reducido a tipo de contenido y bytes. Existe para que los services no dependan de `MultipartFile`; lo arma [[ImageFiles]].'
S['Inquiry'] = 'La Consulta tal como está guardada: id, post (nulo si la publicación fue eliminada), comprador y [[InquiryStatus]]. Ver [[Inquiry and sale flow]].'
S['InquiryDetail'] = 'La Consulta vista por una de sus partes, con su conversación y la reseña propia. Decide qué puede hacer quien mira (aceptar, subir comprobante, cancelar, escribir, calificar) con las mismas reglas que [[InquiryServiceImpl]] aplica antes de escribir. Ver [[Inquiry and sale flow]].'
S['InquiryGroup'] = 'Una publicación y las consultas que la tocaron: la unidad por la que agrupan y paginan las dos bandejas. Es una proyección de lectura, no una tabla.'
S['InquiryPage'] = 'Una página de la bandeja: grupos, número de página y total de páginas. Se pagina por publicación para que un grupo no quede partido. Ver [[Paginated listings]].'
S['InquiryParties'] = 'Comprador y publicante de una Consulta, sin el resto del resumen. Alcanza para decidir pertenencia; lo usa [[InquiryAccessHandler]].'
S['InquiryStatus'] = 'Estados de la Consulta: `PENDING`, `AWAITING_PAYMENT`, `PAYMENT_SUBMITTED`, `ACCEPTED` (venta confirmada), `REJECTED` y `CANCELLED`. `OPEN_STATUSES` reúne los tres primeros: un comprador tiene a lo sumo una Consulta abierta por post. Ver [[Inquiry and sale flow]].'
S['InquirySummary'] = 'La Consulta como la muestran la bandeja y el detalle: partes, álbum, precio congelado, último mensaje, estados de la consulta y del post, dirección y si hay comprobante. Trae las reglas de estado (`isCancellableBy`, `isSale`, `isConversationOpen`). Si el post fue eliminado, el álbum y el vendedor salen de la copia que guarda la consulta.'
S['Message'] = 'Un texto de la conversación de una Consulta: autor, cuerpo y fecha. No se edita ni se borra. Ver [[Conversation flow]].'
S['MessageRules'] = 'Qué texto se acepta como Mensaje: normaliza CRLF a LF, recorta y exige hasta 500 caracteres. La comparten el formulario y [[InquiryServiceImpl]].'
S['PasswordResetToken'] = 'Fila de `password_reset_tokens`: id, Cuenta, token y vencimiento. Un solo enlace vivo por Cuenta. Ver [[Tokens and email links]].'
S['PaymentInfo'] = 'Datos de cobro de una Cuenta: CBU o CVU y alias, cualquiera de los dos opcional. `NONE` representa "sin datos", así `User.getPaymentInfo()` nunca es nulo. Ver [[Addresses and payment flow]].'
S['PaymentInfoRules'] = 'Formato de los datos de cobro: CBU de 22 dígitos con sus dos dígitos verificadores y alias de 6 a 20 caracteres. Normaliza y valida igual en el formulario y en [[UserServiceImpl]].'
S['Post'] = 'La publicación guardada: publicante, álbum, precio, descripción, [[Condition]], año de prensado, zona, foto principal y [[PostStatus]]. Representa un ejemplar único. Ver [[Publish flow]].'
S['PostContactOptions'] = 'Lo que la ficha de un post le ofrece a quien la mira: el [[ContactState]], la Consulta abierta si la hay y si ya está en su carrito. Lo arma [[CartServiceImpl]]. Ver [[Post detail flow]].'
S['PostDetail'] = 'La ficha de una publicación para quien la mira: resumen, perfil público del vendedor (nulo si no está verificado), fotos y si puede editarla (`isEditable`: disponible y propia o moderador). Si puede consultarla lo decide [[PostContactOptions]].'
S['PostPage'] = 'Una página de publicaciones con su número, el total de páginas y si hay anterior y siguiente. Ver [[Paginated listings]].'
S['PostSearchCriteria'] = 'Filtros combinables del catálogo: texto, orden, género, condición, artista, año y rango de precio. Un campo nulo es un filtro que no se aplica. Ver [[Landing flow]].'
S['PostSort'] = 'Los diez órdenes del catálogo. [[PostJdbcDao]] traduce cada valor a un `ORDER BY` fijo, así al SQL nunca entra texto del usuario.'
S['PostStatus'] = 'Estado de la publicación: `AVAILABLE`, `RESERVED` (hay una venta en curso) o `SOLD`. Las transiciones las hace [[PostServiceImpl]] con guarda de estado.'
S['PostSummary'] = 'La publicación unida a su publicante, álbum y artista en una sola fila: lo que muestran las tarjetas y la ficha. Trae también el correo y el idioma del publicante para no volver a buscarlo al mandar un aviso. Evita el N+1 del listado.'
S['PostView'] = 'La pantalla de un post: su [[PostDetail]] y las [[PostContactOptions]] de quien mira. Lo devuelve `CartService.findPostView`.'
S['Province'] = 'Las 24 jurisdicciones de Argentina. El nombre visible sale de i18n (`province.<VALOR>`).'
S['PublicProfile'] = 'El perfil público de una Cuenta: identidad, publicaciones a la venta paginadas, estadísticas y reseñas recientes. Ver [[Public profile flow]].'
S['PublicUserProfile'] = 'Lo único de una Cuenta que se muestra a otros: id, nombre y foto. Sin correo, hash ni datos de cobro.'
S['Receipt'] = 'El comprobante de una venta: tipo de contenido y bytes. `getFilename` le pone la extensión que corresponde al tipo para que se descargue como un archivo reconocible.'
S['ReceiptRules'] = 'Qué comprobante se acepta: PDF, PNG, JPEG o WEBP de hasta 5 MiB; el PDF tiene que empezar con la firma `%PDF-`. La comparten [[ReceiptValidator]] e [[InquiryServiceImpl]].'
S['Review'] = 'Calificación de una parte a la otra en una venta confirmada: consulta, autor, destinatario, nombre del autor, puntaje, comentario, si está activa y fecha. Ver [[Reviews flow]].'
S['ReviewRules'] = 'Puntaje de 1 a 5 y comentario opcional de hasta 500 caracteres, con la misma normalización que un Mensaje. La comparten el formulario, la vista y [[ReviewServiceImpl]].'
S['ReviewStats'] = 'Cantidad y promedio de las reseñas activas de una Cuenta. El promedio llega sin redondear: lo formatea la vista.'
S['SearchResult'] = 'Resultado de una búsqueda: la query ya normalizada, los criterios tal como el service los aplicó, la página y el total de coincidencias. La vista muestra como activo solo lo que el service aplicó de verdad.'
S['SearchSuggestion'] = 'Una sugerencia del buscador: tipo, valor y, para un álbum, el artista.'
S['SearchSuggestionType'] = 'Tipo de sugerencia: `ARTIST` o `ALBUM`. [[PostJdbcDao]] lo emite como literal SQL.'
S['SearchText'] = 'Normalización compartida de búsqueda: minúsculas, sin diacríticos y con separadores reducidos a un espacio (`phrase`), o sin espacios (`compact`). Persistence la usa para llenar `search_phrase` y los services para normalizar lo que se teclea. Ver [[Landing flow]].'
S['ShippingOptions'] = 'Lo que necesita un formulario de envío en una sola lectura: las direcciones activas, la propuesta por defecto y si se puede sumar otra. Lo devuelve `AddressService.findShippingOptions`.'
S['User'] = 'La Cuenta: nombre visible, correo, hash de la contraseña, [[UserRole]], si está verificada, idioma preferido y [[PaymentInfo]]. Inmutable. `verified` no impide iniciar sesión; habilita la authority `VERIFIED`. Ver [[Authentication flow]].'
S['UserRole'] = 'Roles de una Cuenta: `USER` y `ADMIN`. El administrador conserva lo de una Cuenta común y además puede editar y eliminar publicaciones disponibles ajenas.'
S['VinylInputRules'] = 'Límites numéricos compartidos por el catálogo y la carga: años entre 1000 y 9999 y no futuros, precios entre 1 y 99.999.999, rango de precios ordenado y prensado no anterior al lanzamiento.'
# ---------------- persistence-contracts ----------------
S['AddressDao'] = 'Contrato de persistencia de direcciones: crear, buscar por id, listar activas de una Cuenta, archivar y contar activas. Lo implementa [[AddressJdbcDao]].'
S['AlbumDao'] = 'Contrato de persistencia de álbumes: buscar por artista, título y año sin distinguir mayúsculas, crear y actualizar título y género. Lo implementa [[AlbumJdbcDao]].'
S['ArtistDao'] = 'Contrato de persistencia de artistas: buscar o crear por nombre normalizado, actualizar el nombre visible y sugerencias. Lo implementa [[ArtistJdbcDao]].'
S['CartItemDao'] = 'Contrato de persistencia del carrito: agregar, quitar, quitar varios, saber si un post está, y listar o contar filtrando por estado del post y por consultas que lo ocultan. Qué combinación significa "se puede consultar" lo decide el service. Lo implementa [[CartItemJdbcDao]].'
S['DuplicatePostKeyException'] = 'Marca de persistencia: el `INSERT` o `UPDATE` de un post violó la unicidad `(user_id, album_id)`. [[PostServiceImpl]] la traduce a [[DuplicatePostException]]. Existe para que services no dependa de la excepción de Spring.'
S['EmailVerificationTokenDao'] = 'Contrato de los tokens de verificación: crear con fecha, buscar por token, buscar el último de una Cuenta y borrar los de una Cuenta. Ver [[Tokens and email links]].'
S['ImageDao'] = 'Contrato de imágenes: crear, borrar si nadie la referencia y buscar exigiendo pertenencia a un post, un usuario o un álbum.'
S['InquiryDao'] = 'Contrato de consultas: crear una o varias en lote, bandejas paginadas por publicación, resumen y partes, transiciones de estado con guarda, comprobante, consultas abiertas de un comprador, rechazo de las demás pendientes y desenganche al eliminar un post.'
S['MessageDao'] = 'Contrato de mensajes de una conversación: crear y listar por consulta en orden de llegada.'
S['PasswordResetTokenDao'] = 'Contrato de los tokens de recuperación: crear con vencimiento, buscar, borrar por token, borrar por Cuenta y purgar vencidos. Ver [[Tokens and email links]].'
S['PostDao'] = 'Contrato de publicaciones: búsqueda y conteo con filtros, sugerencias, listados por publicante, lectura con bloqueo de una o varias filas, alta, edición, cambio de estado con guarda y borrado.'
S['PostImageDao'] = 'Contrato de la galería: ids de las fotos adicionales en orden, agregar una en una posición y borrar las de un post.'
S['ReviewDao'] = 'Contrato de reseñas: buscar la de un autor en una venta, listar las activas de una Cuenta, estadísticas, crear, actualizar (reactivando) y desactivar.'
S['UserDao'] = 'Contrato de Cuentas: buscar por id o correo, lectura con bloqueo, proyección pública, alta, y actualizaciones condicionales (`completePending`, `markVerified`, `updatePasswordIfMatches`) que resuelven carreras en la base.'
# ---------------- persistence ----------------
S['AddressJdbcDao'] = 'Direcciones con Spring JDBC. El `RowMapper` y la lista de columnas son de paquete para que [[InquiryJdbcDao]] los reutilice al traer la dirección por `JOIN`. Archivar es un `UPDATE ... WHERE archived = FALSE`.'
S['AlbumJdbcDao'] = 'Álbumes con Spring JDBC. Busca por artista, `normalized_title` y año; al crear o editar recalcula `normalized_title` y `search_phrase`. No escribe `cover_image_id`: la portada del álbum es un dato heredado.'
S['ArtistJdbcDao'] = 'Artistas con Spring JDBC. `findOrCreate` inserta dentro de un savepoint: si otra transacción ganó la carrera, vuelve al savepoint y relee, porque PostgreSQL deja la transacción inutilizable tras una violación de unicidad. Las sugerencias se ordenan con un `CASE` en SQL.'
S['CartItemJdbcDao'] = 'Carrito con Spring JDBC. La clave es `(user_id, post_id)`, así que inserta con `execute` y trata el duplicado como "ya estaba". Listar y contar comparten un `FROM` filtrado por estado del post y por `NOT EXISTS` de una consulta abierta del comprador, ordenado por publicante.'
S['EmailVerificationTokenJdbcDao'] = 'Tokens de verificación con Spring JDBC: inserta con su fecha, busca por token, trae el último de una Cuenta y borra por Cuenta.'
S['ImageJdbcDao'] = 'Imágenes con Spring JDBC. Cada lectura exige con `EXISTS` que la imagen pertenezca al post, usuario verificado o álbum de la URL. El borrado lleva cuatro `NOT EXISTS`: solo elimina lo que nadie referencia.'
S['InquiryJdbcDao'] = 'Consultas con Spring JDBC. El resumen sale de un `JOIN` que cubre posts eliminados con `COALESCE` y trae el último mensaje con una subconsulta agregada. La bandeja se pagina por grupo en dos sentencias. Las transiciones y el comprobante son `UPDATE` con guarda de estado. `createAll` inserta en lote.'
S['MessageJdbcDao'] = 'Mensajes con Spring JDBC. Al crear relee la fila para devolver la fecha que puso la base. Ordena por id. El mapper es de paquete para que [[InquiryJdbcDao]] lo reutilice.'
S['PasswordResetTokenJdbcDao'] = 'Tokens de recuperación con Spring JDBC. El vencimiento llega calculado desde el service. `findByToken` devuelve el token aunque esté vencido: quién decide si sirve es el service.'
S['PostImageJdbcDao'] = 'Galería con Spring JDBC: lista los ids por `display_order`, agrega y borra por post.'
S['PostJdbcDao'] = 'Publicaciones con Spring JDBC. Arma el `WHERE` de búsqueda agregando cláusulas fijas con parámetros, comparte ese `WHERE` entre listar y contar, ordena desde un `switch` sobre [[PostSort]], escapa los comodines de `LIKE`, bloquea filas con `FOR UPDATE` (una o varias en orden de id) y cambia estado con guarda.'
S['ReviewJdbcDao'] = 'Reseñas con Spring JDBC. `update` reactiva la fila existente; `deactivate` solo afecta una reseña activa; las estadísticas usan `COUNT` y `AVG` sobre las activas.'
S['UserJdbcDao'] = 'Cuentas con Spring JDBC. Normaliza el correo al buscar y al crear. Los `UPDATE` condicionales (`WHERE password_hash IS NULL`, `WHERE verified = FALSE`, `WHERE password_hash = ?`) hacen que el pedido que pierde una carrera no pise al que ganó. `FOR UPDATE` para los bloqueos de fila.'
# ---------------- services-contracts ----------------
S['AddressLimitExceededException'] = 'La Cuenta ya tiene el máximo de direcciones activas. La lanza [[AddressServiceImpl]]; el perfil, el contacto y el carrito la muestran como aviso.'
S['AddressNotFoundException'] = 'La dirección no existe, es de otra Cuenta o está archivada. [[ErrorResponseAdvice]] la convierte en 404; el contacto y el carrito la tratan como "elegí otra".'
S['AddressService'] = 'Contrato de la libreta: direcciones activas y opciones de envío en una lectura, alta con tope de 3, reemplazo (archiva y crea) y baja lógica.'
S['AlbumService'] = 'Contrato del catálogo de álbumes: buscar o crear por identidad, y resolver al editar actualizando título y género.'
S['ArtistService'] = 'Contrato del catálogo de artistas: buscar o crear por identidad normalizada, resolver al editar y sugerencias para el autocompletado.'
S['CartAddRejectedException'] = 'El post no se pudo agregar al carrito. Lleva el post y el motivo (`OWN_POST`, `UNAVAILABLE`, `ALREADY_IN_CART`, `CART_FULL`) para volver a su ficha con el aviso.'
S['CartService'] = 'Contrato del carrito: agregar, quitar, pantalla de envío, contador, la ficha de un post con lo que se le ofrece a quien mira, y enviar con una dirección guardada o nueva. `MAX_ITEMS` es 20. Ver [[Cart flow]].'
S['ConcurrentPublishException'] = 'Otra publicación simultánea creó el mismo artista o álbum. Esa transacción ya hizo commit, así que reintentar funciona. El formulario lo muestra como error global.'
S['DuplicatePostException'] = 'La Cuenta ya publicó ese álbum. El formulario de publicar o editar lo muestra como error global.'
S['DuplicateUserException'] = 'El correo ya pertenece a una Cuenta con contraseña, o un registro simultáneo se adelantó. El registro lo muestra en el campo de correo con el enlace a recuperar la contraseña.'
S['EmailService'] = 'Contrato de envío de correos: siete operaciones, cada una con el `Locale` como parámetro porque el envío corre en otro hilo. Ver [[Mail delivery]].'
S['ForbiddenOperationException'] = 'La operación existe pero no le corresponde a quien la pide: consultar un post propio, operar una consulta o una dirección ajena. [[ErrorResponseAdvice]] la convierte en 403.'
S['ImageService'] = 'Contrato de imágenes: lectura por pertenencia (post, avatar, álbum), alta validada, borrado condicional y galería.'
S['InquiryEvent'] = 'Los seis cambios de una Consulta que disparan correo: `ACCEPTED`, `RECEIPT_UPLOADED`, `RECEIPT_REQUESTED`, `CONFIRMED`, `CANCELLED` y `REJECTED`. El evento elige las keys de i18n del asunto, el título y el texto.'
S['InquiryNotFoundException'] = 'La Consulta no existe. [[ErrorResponseAdvice]] la convierte en 404.'
S['InquiryService'] = 'Contrato de consultas y ventas: contactar, envío en lote del carrito, bandejas agrupadas, transiciones de la venta, comprobante, conversación, reseñas y consultas de pertenencia para [[InquiryAccessHandler]].'
S['InquiryUpdateNotification'] = 'Carga del correo de un cambio de Consulta: evento, consulta, destinatario y datos del álbum. Reemplazó a la notificación de "aceptada".'
S['InvalidCurrentPasswordException'] = 'La contraseña actual no coincide, o cambió entre la lectura y el `UPDATE`. El perfil la muestra en el campo de clave actual.'
S['InvalidImageException'] = 'La imagen no cumple [[ImageRules]], o al editar se intenta retirar una foto ajena o superar el tope. Los formularios la muestran junto al campo; fuera de ellos, [[ErrorResponseAdvice]] responde 400.'
S['InvalidInquiryStateException'] = 'La transición no encontró la Consulta o el post en el estado esperado. [[InquiryController]] la convierte en 409.'
S['InvalidMessageException'] = 'El texto del Mensaje no cumple [[MessageRules]]. El controller la muestra como error del campo.'
S['InvalidPaymentInfoException'] = 'CBU o alias con formato inválido que llegó al service salteando el formulario.'
S['InvalidPostDataException'] = 'Defensa del contrato de [[PostServiceImpl]]: año o precio fuera de rango. La validación web debería impedir que llegue en un pedido normal.'
S['InvalidReceiptException'] = 'El comprobante no cumple [[ReceiptRules]]. El controller la muestra como error del campo.'
S['InvalidReviewException'] = 'La reseña no cumple [[ReviewRules]]. Solo llega si un POST saltea el formulario; [[ErrorResponseAdvice]] responde 400.'
S['InvalidSearchQueryException'] = 'El texto de búsqueda supera los 255 caracteres. [[LandingController]] responde 400.'
S['MessageNotification'] = 'Carga del correo de "mensaje nuevo": consulta, destinatario, quién escribió, el texto y los datos del álbum.'
S['MissingPaymentInfoException'] = 'El publicante quiso aceptar una consulta sin datos de cobro. [[InquiryController]] redirige al perfil con esa fila abierta.'
S['NothingToSendException'] = 'Al enviar el carrito, ningún post se podía consultar. No se escribe nada y se vuelve al carrito con un aviso.'
S['OpenInquiryExistsException'] = 'El comprador ya tiene una Consulta abierta sobre ese post. Lleva su id para redirigirlo a esa conversación.'
S['PageNotFoundException'] = 'Número de página menor que 1 o mayor que el total. [[ErrorResponseAdvice]] responde 404.'
S['PasswordHasher'] = 'Hashear y comparar contraseñas sin que `services` dependa de Spring Security. El adaptador sobre BCrypt está en [[SecurityConfig]].'
S['PaymentInfoRequiredException'] = 'No se pueden vaciar los datos de cobro con una venta abierta: el comprador se quedaría sin dónde transferir.'
S['PostInterestNotification'] = 'Carga del correo de "consulta nueva": publicante, quién consulta, mensaje opcional y la lista de vinilos (`InterestedPost`) con la Consulta de cada uno. El contacto manda uno; el carrito, todos los de un mismo publicante en un solo correo.'
S['PostNotFoundException'] = 'La publicación no existe. [[ErrorResponseAdvice]] responde 404.'
S['PostService'] = 'Contrato de publicaciones: ficha, búsqueda paginada, sugerencias, listados por publicante, alta, edición y borrado, más las operaciones internas de la venta (`lockById`, `lockByIds`, `reserve`, `release`, `markSold`) que exigen una transacción abierta.'
S['PostUnavailableException'] = 'La publicación ya no está disponible para consultar, editar o eliminar. Los controllers responden 409.'
S['PublicProfileService'] = 'Contrato del perfil público: una operación que compone Cuenta, publicaciones y reseñas.'
S['ReceiptNotFoundException'] = 'La Consulta no tiene comprobante cargado. [[ErrorResponseAdvice]] responde 404.'
S['ReviewService'] = 'Contrato de reseñas. `save` y `remove` son internas de la venta: solo las llama [[InquiryServiceImpl]] dentro de su transacción y no validan permisos.'
S['UnchangedPasswordException'] = 'La contraseña nueva es igual a la actual, en el cambio desde el perfil o en la recuperación. Se muestra en el campo de la clave nueva.'
S['UserNotFoundException'] = 'La Cuenta no existe, o no tiene perfil público. [[ErrorResponseAdvice]] responde 404.'
S['UserService'] = 'Contrato de Cuentas: registro, verificación y reenvío, nombre, avatar, cambio y recuperación de contraseña, datos de cobro y bloqueo de fila para serializar operaciones de una misma Cuenta.'
# ---------------- services ----------------
S['AddressServiceImpl'] = 'Libreta de direcciones con tope de 3 activas. `findShippingOptions` devuelve lista, propuesta y cupo en una lectura; `hasRoom` es la única definición del tope. El alta bloquea la Cuenta; editar archiva y crea; la pertenencia se vuelve a chequear acá. Ver [[Addresses and payment flow]].'
S['AlbumServiceImpl'] = 'Busca o crea el álbum por artista, título y año. Al editar una publicación, si el título o el género difieren, actualiza el registro compartido. El álbum guarda solo datos factuales; las fotos son del post.'
S['ArtistServiceImpl'] = 'Busca o crea el artista por identidad: el nombre en minúsculas, solo letras y dígitos. Al editar puede actualizar el nombre visible compartido. Sugerencias normalizadas con [[SearchText]], hasta 5.'
S['CartServiceImpl'] = 'Carrito de consultas. Agregar valida con [[ContactRules]] y bloquea la Cuenta para el tope de 20. Enviar bloquea los posts en orden de id, vuelve a decidir qué sigue consultable, resuelve la dirección y crea las Consultas en lote; lo omitido queda en el carrito. También arma la ficha con lo que se le ofrece a quien mira. Ver [[Cart flow]].'
S['ContactRules'] = 'La única definición de "se puede consultar": disponible, ajeno y sin una Consulta abierta del comprador. La leen el contacto, el carrito y la ficha, y el carrito le pasa sus constantes al DAO para filtrar en SQL.'
S['EmailServiceImpl'] = 'Arma y envía los siete correos: plantilla Thymeleaf, asunto de i18n, `MimeMessage` HTML en UTF-8. Cada método es `@Async` y atrapa sus errores para loguearlos. La URL base sale de `app.base-url`. Ver [[Mail delivery]].'
S['ImageServiceImpl'] = 'Valida tipo, tamaño y firma antes de guardar; lee por pertenencia; borra solo lo no referenciado; reemplaza la galería completa. Ver [[Cover image flow]] y [[Gallery flow]].'
S['InquiryServiceImpl'] = 'Consultas, ventas, conversación y reseñas. Contactar bloquea el post y congela el precio; cada transición bloquea el post, vuelve a chequear al actor y actualiza con guarda de estado; los avisos salen después del commit en el idioma del destinatario. `submitAll` crea en lote las consultas del carrito. Ver [[Inquiry and sale flow]], [[Contact flow]], [[Conversation flow]] y [[Reviews flow]].'
S['Pagination'] = 'Aritmética de páginas compartida: páginas para un total y offset de una página. Una sola regla para "fuera de rango": la página 1 siempre existe; cualquier otra tiene que caer dentro del total. Ver [[Paginated listings]].'
S['PostServiceImpl'] = 'Publicaciones. Busca con normalización y filtros saneados, contando antes de listar. Publica y edita artista, álbum, fotos y post en una transacción, traduciendo las carreras a errores de negocio. Elimina desenganchando las consultas. Expone bloqueo y transiciones para la venta con propagación `MANDATORY`. Ver [[Landing flow]], [[Publish flow]] y [[Edit and delete flow]].'
S['PublicProfileServiceImpl'] = 'Compone el perfil público con la Cuenta verificada, sus publicaciones disponibles y sus reseñas. Vive aparte porque [[PostService]] ya depende de [[UserService]]. Ver [[Public profile flow]].'
S['ReviewServiceImpl'] = 'Guarda (actualizando la fila existente o creando) y quita (borrado lógico) reseñas con propagación `MANDATORY`; lee la reseña activa, las recientes y las estadísticas. Ver [[Reviews flow]].'
S['SupportedLocales'] = 'Idiomas que la aplicación sabe hablar (`es`, `en`, `fr`). Normaliza antes de guardar `preferred_locale` y antes de elegir el idioma de un correo.'
S['TransactionCallbacks'] = 'Difiere una acción hasta después del commit de la transacción en curso; sin transacción la ejecuta en el momento. Lo usan todos los envíos de correo. Ver [[Mail delivery]].'
S['UserServiceImpl'] = 'Cuentas: registro con Cuenta sin verificar, verificación, reenvío con espera de un minuto, cambio y recuperación de contraseña, nombre, avatar y datos de cobro. Genera los tokens, resuelve las carreras con actualizaciones condicionales y registra cada correo para después del commit. Ver [[Authentication flow]], [[Password recovery flow]] y [[Tokens and email links]].'
# ---------------- webapp ----------------
S['SecurityConfig'] = 'Configuración de Spring Security: BCrypt 12 y su adaptador `PasswordHasher`, beans de pertenencia para `@PreAuthorize`, la lista única de rutas de Cuenta verificada, form login por correo, logout, registro de sesiones y el handler que distingue "verificá tu correo" de 403. Ver [[Security and authorization]].'
S['WebConfig'] = 'Configuración de Spring: escaneo de componentes, `DataSource`, transacciones, Flyway al arrancar, resolver multipart, vistas JSP, `Locale`, i18n, validador, JavaMail, Thymeleaf para correos y el pool de hilos de `@Async`. Ver [[Startup and dependency injection]].'
S['ArtistSuggestionController'] = '`GET /artists/suggestions`: devuelve en JSON hasta cinco artistas para el autocompletado del formulario de publicar. Ver [[Search suggestions flow]].'
S['AuthenticationController'] = 'Login (solo la vista), registro con inicio de sesión automático, verificación por enlace, página de aviso, reenvío con espera y recuperación de contraseña en dos pasos. Ver [[Authentication flow]] y [[Password recovery flow]].'
S['CartController'] = 'Carrito: ver, agregar desde la ficha (vuelve al listado de origen), quitar y enviar. Los rechazos esperables los resuelve [[CartExceptionAdvice]]. Ver [[Cart flow]].'
S['CartCountAdvice'] = 'Deja en cada request, para Cuentas verificadas, un contador perezoso del carrito que la cabecera lee. Es atributo del request y no del modelo para no colarse como parámetro en los `redirect:`.'
S['CartExceptionAdvice'] = 'Solo para [[CartController]] y con prioridad sobre [[ErrorResponseAdvice]]: convierte los motivos por los que el carrito no puede agregar o enviar en una redirección a la pantalla de origen con su aviso.'
S['ErrorController'] = 'Vistas de 403 y 404 a las que hacen forward Spring Security y el contenedor. Pasar por un controller hace que el error use el mismo view resolver y el mismo `Locale` que el resto.'
S['ErrorResponseAdvice'] = 'Único lugar donde las excepciones de negocio se vuelven respuestas: no encontrado → 404, ajeno → 403, dato que saltea la validación o parámetro mal tipado → 400. Ver [[Security and authorization]].'
S['ImageController'] = 'Sirve imágenes desde el recurso al que pertenecen (post, usuario, álbum) con caché de un año; 404 sin cuerpo si no corresponde. Ver [[Cover image flow]].'
S['InquiryController'] = 'Bandejas, página de la consulta y un endpoint por transición de la venta, además de mensajes, reseñas y descarga del comprobante con headers de seguridad. Cada endpoint lleva su `@PreAuthorize`. Ver [[Inquiry and sale flow]].'
S['LandingController'] = 'Catálogo en `GET /`: liga los filtros de la URL ignorando valores de enum inválidos y delega todo en [[PostService]]; muestra como activo lo que el service aplicó. Ver [[Landing flow]].'
S['ListingQueries'] = 'Sanea el parámetro `from` (la query del listado de origen): solo acepta caracteres de una query ya codificada. Cualquier otra cosa se descarta.'
S['PostContactController'] = 'Formulario de contacto de una publicación: carga el post contactable y las opciones de envío, y envía la consulta con dirección guardada o nueva. Ver [[Contact flow]].'
S['PostController'] = 'Ficha pública `GET /post/{id}`: pide a [[CartService]] la ficha con lo que se le ofrece a quien mira y resuelve a dónde volver. Ver [[Post detail flow]].'
S['PostOrigin'] = 'De dónde se llegó a una ficha: perfil público o perfil propio. Al ser un enum, la ruta de regreso no se arma con texto libre.'
S['ProfileController'] = 'Perfil privado: nombre, foto, contraseña, datos de cobro y libreta de direcciones, con las publicaciones propias paginadas. Cada fila es un POST propio. Ver [[Profile flow]] y [[Addresses and payment flow]].'
S['PublicProfileController'] = '`GET /users/{id}`: perfil público con publicaciones a la venta y reseñas. Ver [[Public profile flow]].'
S['PublishController'] = 'Publicar, editar y eliminar. Editar y eliminar exigen ser el publicante o administrador (`@PreAuthorize`); que el post siga disponible lo exige el service. Ver [[Publish flow]] y [[Edit and delete flow]].'
S['SearchSuggestionController'] = '`GET /search/suggestions`: sugerencias de álbum y artista en JSON, con la etiqueta del tipo traducida en el servidor. Ver [[Search suggestions flow]].'
S['ArtistSuggestionDto'] = 'Forma JSON de una sugerencia de artista: solo `value`.'
S['SearchSuggestionDto'] = 'Forma JSON de una sugerencia del buscador: `value`, `type`, `typeLabel` y `detail`. Separa el contrato JSON del modelo de dominio.'
S['ImageNotFoundException'] = 'La imagen no existe o no pertenece al recurso de la URL. [[ImageController]] responde 404 sin cuerpo.'
S['AddressForm'] = 'Formulario de una dirección de la libreta: calle, altura, ciudad, provincia y código postal obligatorios, con sus largos máximos.'
S['AvatarForm'] = 'Formulario de la foto de perfil: un archivo o la marca `remove`. Lo valida [[AvatarFormValidator]].'
S['CatalogFilterForm'] = 'Filtros del catálogo ligados desde la URL: texto, orden, género, condición, artista, año y precios. `toCriteria` los pasa a [[PostSearchCriteria]].'
S['ChangePasswordForm'] = 'Cambio de contraseña desde el perfil: clave actual obligatoria, nueva con [[ValidPassword]] y confirmación con [[MatchingPasswords]].'
S['ContactForm'] = 'Formulario de contacto: hereda la dirección de [[ShippingAddressForm]] y suma el mensaje opcional de hasta 500 caracteres.'
S['ForgotPasswordForm'] = 'Pedido de recuperación: solo el correo, obligatorio, con formato y hasta 100 caracteres.'
S['ImageFiles'] = 'Puente entre `MultipartFile` y [[ImageUpload]]: detecta archivo presente, valida con [[ImageRules]] mirando el tamaño antes de leer los bytes y convierte.'
S['LineBreakNormalizingEditor'] = 'Editor de binding que normaliza CRLF a LF y recorta. El navegador cuenta un salto como un carácter en `maxlength` pero lo envía como dos; sin esto `@Size` rechazaría un texto válido.'
S['LoginForm'] = 'Bean con correo y contraseña para dibujar el formulario de login. La autenticación la hace Spring Security, no un controller.'
S['MessageForm'] = 'Un Mensaje nuevo: texto obligatorio hasta 500 caracteres. [[InquiryServiceImpl]] vuelve a aplicar [[MessageRules]].'
S['PaymentForm'] = 'Datos de cobro: CBU y alias, los dos opcionales (vaciarlos borra los datos). Lo valida [[PaymentFormValidator]].'
S['ProfileForm'] = 'Edición del nombre visible: obligatorio y hasta 100 caracteres.'
S['PublishForm'] = 'Formulario de publicar y editar: título, artista, año, género, precio, condición, zona, prensado, descripción, fotos nuevas y fotos a retirar. Reglas cruzadas en [[PublishFormValidator]].'
S['ReceiptForm'] = 'Formulario del comprobante: un archivo validado con [[ValidReceipt]].'
S['RegisterForm'] = 'Registro: correo, nombre, contraseña con [[ValidPassword]] y confirmación con [[MatchingPasswords]].'
S['ResetPasswordForm'] = 'Recuperación: token oculto obligatorio, contraseña nueva con [[ValidPassword]] y confirmación.'
S['ReviewForm'] = 'Reseña: puntaje obligatorio de 1 a 5 y comentario opcional hasta 500. `of` precarga la reseña vigente para editarla.'
S['ShippingAddressForm'] = 'Dirección de envío de una Consulta: una guardada (`addressId`) o una nueva con estos mismos campos. Los campos no llevan `@NotBlank` porque solo son obligatorios al cargar una nueva. Lo usan el contacto y el carrito.'
S['AddressAccessHandler'] = 'Bean `addressAccess` de `@PreAuthorize`: solo el dueño edita o elimina una dirección. Una dirección inexistente pasa, para que el service responda 404.'
S['AuthenticatedUser'] = 'El principal de la sesión: adapta la Cuenta a `UserDetails`. Authorities `ROLE_USER`, `ROLE_ADMIN` y `VERIFIED`; `isEnabled` siempre verdadero para que una Cuenta sin verificar pueda entrar; `equals` por id para que el registro de sesiones agrupe bien. Ver [[Authentication flow]].'
S['AuthenticatedUserDetailsService'] = 'Carga la Cuenta por correo para el login. Si no existe o no tiene contraseña, responde con el mismo error genérico.'
S['AuthenticationSessions'] = 'Tres operaciones sobre la sesión: iniciar sesión sin pasar por el login (registro), refrescar el principal (verificación, cambio de nombre) y cerrar todas las sesiones de una Cuenta (cambio o recuperación de clave).'
S['InquiryAccessHandler'] = 'Bean `inquiryAccess` de `@PreAuthorize`: comprador, publicante o cualquiera de las dos partes de una consulta. Una consulta inexistente pasa, para que el service responda 404.'
S['MultipartExceptionHandlerFilter'] = 'Filtro que envuelve al multipart: si el request excede el tamaño máximo, redirige al formulario de origen con un aviso en lugar de un error 500.'
S['PostAccessHandler'] = 'Bean `postAccess` de `@PreAuthorize`: quien edita o elimina es el publicante. El administrador entra por rol en la misma expresión.'
S['SameSiteRedirects'] = 'Convierte el header `Referer` en una ruta de regreso segura: mismo host, dentro del context path y sin `//` ni barra invertida. Evita una redirección abierta.'
S['VerificationAccessDeniedHandler'] = 'Una Cuenta sin verificar que entra a una ruta de Cuenta verificada va a `/verify/required`; cualquier otra denegación sigue siendo 403.'
S['AvatarFormValidator'] = 'Quitar la foto no necesita archivo; cambiarla exige una imagen que cumpla [[ImageRules]].'
S['CatalogFilterValidator'] = 'Valida año y precios de los filtros y que el rango esté ordenado, colgando cada error de su campo.'
S['MatchingPasswords'] = 'Restricción de clase para formularios con contraseña y confirmación ([[PasswordsMatching]]).'
S['MatchingPasswordsValidator'] = 'Compara contraseña y confirmación y cuelga el error del campo de confirmación.'
S['PasswordsMatching'] = 'Interfaz con los dos getters que necesita [[MatchingPasswordsValidator]]; la implementan los tres formularios con contraseña.'
S['PaymentFormValidator'] = 'Vacío es válido. Si hay CBU o alias, normaliza y valida con [[PaymentInfoRules]], igual que el service.'
S['PublishFormValidator'] = 'Reglas cruzadas de publicar: años válidos y no futuros, precio en rango, prensado no anterior al lanzamiento y hasta 5 fotos válidas.'
S['ReceiptValidator'] = 'Valida el comprobante con [[ReceiptRules]] mirando el tamaño antes de leer los bytes.'
S['ShippingAddressValidator'] = 'Con dirección guardada elegida no valida nada; al cargar una nueva exige calle, altura, ciudad, código postal y provincia.'
S['ValidAvatarForm'] = 'Anotación de clase que aplica [[AvatarFormValidator]].'
S['ValidCatalogFilters'] = 'Anotación de clase que aplica [[CatalogFilterValidator]].'
S['ValidPassword'] = 'Restricción compuesta de contraseña: obligatoria, de 12 a 72 caracteres (el tope de BCrypt), con al menos una letra y un número.'
S['ValidPaymentForm'] = 'Anotación de clase que aplica [[PaymentFormValidator]].'
S['ValidPublishForm'] = 'Anotación de clase que aplica [[PublishFormValidator]].'
S['ValidReceipt'] = 'Anotación de campo que aplica [[ReceiptValidator]].'
S['ValidShippingAddress'] = 'Anotación de clase que aplica [[ShippingAddressValidator]].'
# ---------------- tests ----------------
T['TestConfiguration'] = 'Contexto de los tests de persistencia: HSQLDB en memoria con sintaxis PostgreSQL, las mismas migraciones Flyway que producción y después los fixtures de `populator.sql`.'
T['InMemoryImageService'] = 'Doble de [[ImageService]] en memoria para los tests de services: aplica las mismas [[ImageRules]] y permite assertear el estado guardado sin `Mockito.verify`.'
T['UserJdbcDaoTest'] = 'Altas, búsquedas por correo normalizado y las actualizaciones condicionales de la Cuenta (`completePending`, `markVerified`, cambio de clave).'
T['EmailVerificationTokenJdbcDaoTest'] = 'Crear, buscar por token, último de una Cuenta y borrado de tokens de verificación.'
T['PasswordResetTokenJdbcDaoTest'] = 'Crear, unicidad por Cuenta, borrado por token y por Cuenta y purga de vencidos.'
T['PostJdbcDaoTest'] = 'Búsqueda con filtros, órdenes, comodines literales, conteo, sugerencias, bloqueo, cambio de estado con guarda, edición y borrado.'
T['InquiryJdbcDaoTest'] = 'Bandejas agrupadas y paginadas (incluidos posts eliminados), guardas de estado, comprobante, consultas abiertas, alta en lote y desenganche.'
T['ImageJdbcDaoTest'] = 'Lectura por pertenencia a post, usuario y álbum, y borrado condicional.'
T['CartItemJdbcDaoTest'] = 'Agregar, repetidos, quitar, quitar varios y el filtro de consultables por estado del post y consultas abiertas.'
T['AddressJdbcDaoTest'] = 'Alta, activas por Cuenta, archivado con guarda y conteo.'
T['AlbumJdbcDaoTest'] = 'Identidad sin distinguir mayúsculas, alta y actualización de metadatos.'
T['ArtistJdbcDaoTest'] = 'Buscar o crear por nombre normalizado, nombre visible y sugerencias sin tildes.'
T['MessageJdbcDaoTest'] = 'Alta de mensajes y orden por llegada.'
T['PostImageJdbcDaoTest'] = 'Orden de la galería, alta y borrado por post.'
T['ReviewJdbcDaoTest'] = 'Alta, actualización que reactiva, desactivación, estadísticas y listado de activas.'
T['UserServiceImplTest'] = 'Registro (nuevo, duplicado, pendiente, carrera), verificación, reenvío con espera, cambio y recuperación de contraseña y datos de cobro, con DAOs simulados.'
T['InquiryServiceImplTest'] = 'Contactabilidad, alta, bandejas, cada transición de la venta con sus estados inválidos, direcciones parciales, mensajes, reseñas, alta en lote y avisos después del commit.'
T['PostServiceImplTest'] = 'Normalización de la búsqueda, filtros inválidos, paginación, publicar, editar con galería, eliminar y bloqueos.'
T['CartServiceImplTest'] = 'Agregar con cada motivo de rechazo, tope, pantalla de envío, envío parcial, nada para enviar y dirección nueva.'
T['ContactRulesTest'] = 'Las combinaciones de estado del post, dueño y consulta abierta, con y sin sesión.'
T['EmailServiceImplTest'] = 'Plantillas reales con un remitente falso: enlaces, asuntos por idioma, escape del texto, un vinilo o varios, y errores que no se propagan.'
T['AddressServiceImplTest'] = 'Opciones de envío, tope de direcciones, reemplazo, archivado y pertenencia.'
T['AlbumServiceImplTest'] = 'Buscar o crear y resolver al editar.'
T['ArtistServiceImplTest'] = 'Identidad normalizada, edición del nombre visible y sugerencias.'
T['ImageServiceImplTest'] = 'Validación de tipo, tamaño y firma, y reemplazo de galería.'
T['PaginationTest'] = 'Páginas para totales vacíos, exactos y con resto; offsets y páginas fuera de rango.'
T['PublicProfileServiceImplTest'] = 'Composición del perfil público.'
T['ReviewServiceImplTest'] = 'Guardar, reemplazar, quitar y reglas de la reseña.'
